    "summary": "Group individual data rows into summary records and compute aggregate metrics (COUNT, SUM, AVG).",
    "theory": "`GROUP BY` collapses rows that share common values in specified columns into summary rows. Non-aggregated columns in the SELECT clause must be included in the GROUP BY expression. It is essential for calculating departmental payrolls, regional sales, or daily transaction counts.",
    "pro_tip": "Ensure numeric columns used in `AVG()` or `SUM()` handle NULL values properly; SQL aggregates ignore NULLs except in `COUNT(*)`.",
    "expected_output": "Department summary: Department name, employee count, and average salary.",
    "sql_file": "20 SQL Query GROUP BY.sql",
    "html_file": "notes/topic-20-group-by-clause.html",
    "slug": "topic-20-group-by-clause",
    "raw_sql": "--Group By\n\nUSE Google;\n\nSELECT * FROM employee;\n\nSELECT SUM(SALARY) FROM employee;\n\nSELECT SUM(SALARY) AS Total_salary FROM employee;\n\n--AGGREGATE FUNCTION are the mathematical function.  (ex:- SUM)\n\nSELECT department, SUM(SALARY) as Total_sal FROM employee GROUP BY department;\n\nSELECT gender, SUM(SALARY) AS Total_salary FROM employee GROUP BY gender;\n\nSELECT department, gender, SUM(SALARY) AS Total_salary FROM employee\nGROUP BY department, gender;\n\nSELECT department, gender, SUM(SALARY) AS Total_salary FROM employee\nGROUP BY department, gender ORDER BY department;\n\nSELECT DEPARTMENT, SUM(SALARY) AS Total_salary FROM employee GROUP BY DEPARTMENT ORDER BY DEPARTMENT;\n\n--Always include non-aggregated columns used in SELECT inside the GROUP BY\nSELECT department, gender, SUM(salary)\nFROM employee\nGROUP BY department;\n\n--Fixed code\nSelect department, gender, SUM(salary)\nFROM employee\nGROUP BY department, gender;\n\n\nselect * from employee"
