    "raw_sql": "--join more than two tables.\n\nUSE Google\n\nSELECT * FROM employee \n\nSELECT * FROM Project\n\nSELECT * FROM Company\n\nSELECT * FROM Employee e inner join project p on e.id = p.pid inner join company c on p.pid = c.cid\n\nselect e.id, e.name, e.gender, e.age, e.salary, e.department, p.project_name,\np.technology, p.pincode, c.company_name, c.headquaters from employee e \ninner join project p on e.id = p.pid inner join company c on p.pid = c.cid \nwhere c.headquaters = 'seattle'\n\n\nselect e.id, e.name, e.gender, e.age, e.salary, e.department, p.project_name,\np.technology, p.pincode, c.company_name, c.headquaters from employee e \ninner join project p on e.id = p.pid inner join company c on p.pid = c.cid \nwhere e.gender = 'male' order by e.name\n\nselect e.id as EmpId, e.name as FirstName, e.gender, e.age, e.salary as Earnings\n, e.department, p.project_name,\np.technology as Domain, p.pincode, c.company_name, c.headquaters from employee e \ninner join project p on e.id = p.pid inner join company c on p.pid = c.cid \n\nselect p.technology, sum(e.salary) as Total_salary from employee e inner join \nproject p on e.id = p.pid inner join company c\non p.pid = c.cid group by p.technology"
