    "raw_sql": "--CTE\n\nuse google\nselect * from employee\n\nselect * from employee where name = 'mark'\n\ndelete top(6) from employee where name = 'mark'\n\nselect * from employee\n\ninsert into employee values (35, 'Rudra', 29, 'Male', 150000, 'IT', 'Delhi', 'India')\n\ninsert into employee values(36, 'Priya', 55, 'Female', 45000, 'HR', 'Mumbai', 'India')\n\ninsert into employee values(37, 'Vijay', 34, 'Male', 50000, 'Marketing', 'Amritsar', 'India')\n\ninsert into employee values (38, 'Sherry', 40, 'Female', 45000, 'HR', 'Aukland', 'New Zealand') \n\n\nselect * from employee\n\nselect *, row_number() over (partition by id order by id) as Id_no from employee\n\nwith Lion as\n(\nselect *, row_number() over (partition by id order by id) as Id_no from employee\n)\ndelete from Lion where id_no > 1\n\nselect * from employee\n\n\n\ninsert into employee values (39, 'Siva', 29, 'Male', 150000, 'IT', 'Delhi', 'India')\n\ninsert into employee values(40, 'Payal', 55, 'Female', 45000, 'HR', 'Mumbai', 'India')\n\ninsert into employee values(41, 'Varun', 34, 'Male', 50000, 'Marketing', 'Amritsar', 'India')\n\ninsert into employee values (42, 'Sharline', 40, 'Female', 45000, 'HR', 'Aukland', 'New Zealand') \n\n\nselect * from employee\n\nwith Class as \n(\nselect * , row_number() over (partition by id order by id) as Rownumber from employee\n)\ndelete from Class where rownumber > 1\n\n\nselect * from employee\n\nwith Lion as\n(\nselect *, row_number() over (partition by id order by id) as Id_no from employee\n)\ndelete from Lion where id_no > 1\n\nselect * from Employee"
